import { ref, onMounted } from 'vue';
import Navbar from './components/Navbar.vue';
export default {
  name: 'App',
  components: {
    Navbar
  },
  setup() {
    const loading = ref(true);
    const onPageLoaded = () => {
      loading.value = false;
    };
    onMounted(() => {
      // Simulate minimum loading time to ensure smooth transition
      setTimeout(() => {
        if (loading.value) {
          loading.value = false;
        }
      }, 500);
    });
    return {
      loading,
      onPageLoaded
    };
  }
};
